/* 念念陈列室 · 设计 DNA · tokens · 方向 A「旧信」
 * Hallmark: genre=editorial · theme=Almanac(warm-cream) · accent=terracotta · display=high-contrast-serif
 * 这些值与阶段一敲定的 demo（A-旧信.html）逐一对齐——工程照它做、品味验收拿它当尺，勿凭空改。
 */
:root{
  /* —— 颜色 —— */
  --color-sand:#e7dcc7;          /* 最外层·暖沙背景 */
  --color-paper:#f4ecdd;         /* 应用纸面 */
  --color-paper-2:#f7efe0;       /* 抽屉/浅分区底 */
  --color-card:#fbf6ec;          /* 卡片/物件缩略底 */
  --color-ink:#2c2620;           /* 主文字·深褐 */
  --color-ink-soft:#6b6152;      /* 次文字·灰褐 */
  --color-line:#d9cdb6;          /* 描边·暖 */
  --color-accent:#a8572f;        /* 强调·陶土红（选中/手柄/CTA/kicker）*/
  --color-accent-soft:#c98a5b;
  --color-accent-tint:#fbeee2;   /* 强调浅底（激活态 chip）*/
  --color-popup:rgba(250,244,232,.87);      /* 半透明弹窗底（需配 backdrop-blur）*/
  --color-popup-line:rgba(168,87,47,.42);   /* 弹窗描边 */

  /* —— 字体（两族：衬线展示 + 系统无衬线 UI）—— */
  --font-serif:Georgia,"Songti SC","Times New Roman",serif;             /* 品牌/标题/故事正文 */
  --font-sans:system-ui,-apple-system,"PingFang SC","Helvetica Neue",sans-serif; /* UI 标签/按钮/说明 */

  /* —— 字阶 —— */
  --text-brand:20px;  --text-title:22px;  --text-body:14.5px;
  --text-label:11px;  --text-kicker:10.5px; --text-meta:11.5px;

  /* —— 间距（4pt 基）—— */
  --space-xs:6px; --space-sm:10px; --space-md:16px; --space-lg:22px;

  /* —— 圆角 —— */
  --radius-sm:6px; --radius-md:10px; --radius-lg:12px; --radius-pill:999px;

  /* —— 描边 / 变换手柄 —— */
  --rule:1px;
  --handle-size:12px;
  --handle-bg:#fbf6ec;
  --handle-border-w:1.6px;         /* 手柄描边宽·陶土红 */
  --handle-hit:24px;               /* 手柄触摸命中区（横屏手机）*/

  /* —— 动效 —— */
  --dur-fast:.18s;
  --ease-out:cubic-bezier(.22,.61,.36,1);

  /* —— 阴影 —— */
  --shadow-card:0 6px 16px -8px rgba(60,40,20,.40);
  --shadow-float:0 22px 48px -16px rgba(60,40,20,.60);
  --shadow-item:drop-shadow(0 12px 16px rgba(0,0,0,.45)); /* 摆放物件的投影（跟随抠图轮廓）*/
