/* ============================================================
 * v2 增补 · 方向 A2「旧信 · 沉浸」（调向敲定，与 A2-旧信-沉浸.html 逐一对齐）
 * 满屏沉浸外壳三件套：浮层玻璃 / Canva 式手柄 / 场景自适应层。
 * ============================================================ */
:root{
  /* —— 浮层玻璃（报头/场景条/物件 dock/小工具条的统一材质）—— */
  --glass-bg:rgba(250,244,232,.78);       /* 玻璃底·半透明奶油 */
  --glass-bg-soft:rgba(250,244,232,.58);  /* 更透的一档（提示条等） */
  --glass-line:rgba(226,213,190,.75);     /* 玻璃描边 */
  --glass-blur:16px;                      /* backdrop-blur 半径 */
  --shadow-glass:0 10px 34px -14px rgba(40,25,10,.5);

  /* —— 手柄 v2（Canva 式：白圆点＋旋转钮＋浮动小工具条）—— */
  --h2-size:13px;                         /* 角手柄圆点直径 */
  --h2-bg:#ffffff;
  --h2-line:rgba(62,46,30,.32);
  --h2-shadow:0 1px 5px rgba(20,12,4,.38);
  --sel-line:rgba(168,87,47,.95);         /* 选框描边·陶土红 */
  --h2-hit:26px;                          /* 触摸命中区（视觉尺寸不变） */

  /* —— 工艺底线 —— */
  --text-label-min:11px;                  /* UI 标签/分区标题字号下限（低于此判不合格） */
}
