// statemachine.mjs —— 状态机：所有状态流转的唯一执行者。
// 流转表只认 schemas.mjs 里的 TRANSITIONS，表里没有的路一律非法、当场抛错。
// 三条硬规矩在这里落地：
//   ① 进阶段二必须先有签字文件 + 品味 demo（没谈完 / 没让老板看过能看的 demo 不许开工）；
//   ② 里程碑每失败一次记一笔，失败满 INCIDENT_STRIKES 次自动置 incident（三振熔断，等人处理）；
//   ③ 全部里程碑 done 时往事件流水记一笔「项目完成」。
// 本文件对 .opc/ 的读写全部经 store，绝不直接碰文件系统。

import path from 'node:path';
import { TRANSITIONS, INCIDENT_STRIKES, WRITE_TYPES, PATHS, TASTE_EXAMPLE_KINDS } from './schemas.mjs';
import { readJson, writeJson, appendLine, listOpcDir } from './store.mjs';
import { listArtifacts } from './artifact.mjs';

// 里程碑清单的存放位置以写入类型表声明的为准，不另抄一份路径字面量。
const MILESTONES_REL = WRITE_TYPES['phase1-milestones'].path();
// 品味 demo 的存放目录（从写入类型表推出，不另抄字面量）。
const TASTE_EXAMPLES_REL = path.posix.dirname(WRITE_TYPES['taste-example'].path('占位.html'));

// 品味是否留过能看的真实 demo：examples/ 下有认得后缀的例子文件。
async function hasTasteDemoFile(root) {
  const names = await listOpcDir(root, TASTE_EXAMPLES_REL);
  return names.some((n) => Object.keys(TASTE_EXAMPLE_KINDS).some((s) => n.endsWith(s)));
}

// 品味 demo 是否登记进了画廊 manifest（source=taste/*）。2026-07-16 收紧（老板拍板）：
// 光有文件不够——老板只经 hub 画廊/Preview 看 demo，manifest 没条目＝老板从没看见过它。
// 走 write taste-example 通道落盘会自动登记（opc.mjs text 分支）；绕通道直接写文件、或
// 登记那步挂了被吞（该处 try/catch 只打 stderr），都会在这里被拦下来，逼回正规通道。
async function hasTasteDemoRegistered(root) {
  const entries = await listArtifacts(root);
  return entries.some((a) => typeof a?.source === 'string' && a.source.startsWith('taste/'));
}

// 非法流转专用错误：CLI 层认出它之后转成 EXIT.ILLEGAL_TRANSITION 退出码。
export class IllegalTransition extends Error {
  constructor(message) {
    super(message);
    this.name = 'IllegalTransition';
  }
}

// 查流转表：当前状态到目标状态有没有路。没有就抛非法流转，绝不放行。
function assertTransition(kind, from, to) {
  const table = TRANSITIONS[kind];
  const targets = table[from];
  if (!Array.isArray(targets) || !targets.includes(to)) {
    throw new IllegalTransition(`${kind} 不允许从「${from}」流转到「${to}」`);
  }
}

// 读 state.json，不存在就报错——它是模板自带的底档，缺了说明项目坏了。
async function readState(root) {
  const state = await readJson(root, PATHS.state);
  if (state === null) {
    throw new Error(`找不到 ${PATHS.state}，项目状态档缺失，没法推状态`);
  }
  return state;
}

